function readinessRecord(caseNumber:1|2=1){return {kind:'copilot-mounted-history-readiness-v1' as const,caseNumber,journey:caseNumber===1?'follow' as const:'history-reading' as const,threadId:`native-thread-${caseNumber}`,attemptCount:1,outcome:'ready' as const,reason:'content-ready' as const,first:{status:'ready' as const,reason:'content-ready' as const,mountedRows:1,emptyRows:0,firstRowId:null,firstRowRole:null},last:{status:'ready' as const,reason:'content-ready' as const,mountedRows:1,emptyRows:0,firstRowId:null,firstRowRole:null},qualification:false as const};}
