function captureEnvelope(text='\0'.repeat(512),exitNull=false){const stream=()=>({readableEOF:false,writerFinish:false,writerClose:false,writerError:false,seen:Number.MAX_SAFE_INTEGER,retained:Number.MAX_SAFE_INTEGER,retainedBytesKnown:false,overflow:false});return {argv:['a'.repeat(8176),'b','c','d'],original:{exitCode:-2147483648,signal:'\0'.repeat(64),stdoutBytes:Number.MAX_SAFE_INTEGER,stderrBytes:Number.MAX_SAFE_INTEGER,stdoutRetainedBytes:Number.MAX_SAFE_INTEGER,stderrRetainedBytes:Number.MAX_SAFE_INTEGER,closed:false,streamsComplete:false},spawned:false,spawnError:text,timedOut:false,terminationRequested:false,exitObserved:!exitNull,exit:exitNull?null:{exitCode:-2147483648,signal:'\0'.repeat(64)},closeObserved:false,streamFacts:{stdout:stream(),stderr:stream()},descendantClosure:'unqualified',qualification:false};}
