test.each(['\0','\ud800','\\','"','é','😀'])('capture argv uses actual JSON bytes at 8192/+1 with escaped input %#',text=>{const value=captureEnvelope(),unit=Buffer.byteLength(JSON.stringify(text))-2,repeats=Math.floor(8176/unit),rest=8176-repeats*unit;value.argv[0]=text.repeat(repeats)+'a'.repeat(rest);expect(Buffer.byteLength(JSON.stringify(value.argv))).toBe(8192);expect(tool.constructMountedCaptureResult(value)).toEqual(value);value.argv[0]+='a';expect(()=>tool.constructMountedCaptureResult(value)).toThrow();});
test('real worst control capture encoding is 12882 bytes and physically persists unchanged under both pilot 16384 caps',async()=>{const directory=await mkdtemp(join(tmpdir(),'tracker-a-capture-bound-'));try{const failure=tool.serializeMountedFailure('run',Error('\0'.repeat(512))),reason=JSON.parse(Buffer.from(failure.raw).toString()).reason as string,value=captureEnvelope(reason);value.exitObserved=false;const result=tool.constructMountedCaptureResult(value),bytes=Buffer.from(JSON.stringify(result)+'\n');expect(bytes.length).toBe(12882);for(const name of ['parent-result.json','application-result.json']){expect(await tool.writeTrackerAPilotFile(directory,name,bytes,16384)).toMatchObject({path:name,bytes:12882});expect(await readFile(join(directory,name))).toEqual(bytes);}}finally{await rm(directory,{recursive:true,force:true});}});
test.each(['prepare','install','provision','run','parent','child','native-child'] as const)('real fixed failure constructor fits 4096 for %s with original boundedError behavior',action=>{for(const text of ['\0','\ud800','\\','"','é','😀'])for(const workerImport of ['fulfilled','rejected'] as const){const result=tool.serializeMountedFailure(action,Error(text.repeat(512)),workerImport);expect(result.cap).toBe(4096);expect(result.raw.byteLength).toBeLessThanOrEqual(4096);const data=JSON.parse(Buffer.from(result.raw).toString());expect(data.reason).toBe(text.repeat(512).slice(0,512));expect(data.qualification).toBe(false);expect(Object.keys(data)).toEqual(action==='native-child'?['workerImport','reason','qualification']:['action','reason','status','qualification']);}});

