function held<T>(){let yes!:(value:T)=>void,no!:(error:unknown)=>void;const promise=new Promise<T>((resolve,reject)=>{yes=resolve;no=reject;});return {promise,resolve:yes,reject:no};}
test.each(['child','parent'] as const)('actual %s controller prearms failure before complete-looking bytes and every original publication wait',async action=>{for(const status of ['complete','incomplete'] as const)for(const phase of ['fsync','close','authenticate'] as const){let exit:number|undefined,visible=false;const gate=held<void>();const source=action==='child'?tool.constructTrackerAChildResult(await projectionNative(),persisted()):await parentEnvelope();const report={...source as object,status};const work=tool.runTrackerAPilotAction(action,()=>tool.publishTrackerAInternalReport(action,report,async value=>tool.closeTrackerAPilotFile(Buffer.from(JSON.stringify(value)),{write:async()=>{visible=true;},fsync:()=>phase==='fsync'?gate.promise:Promise.resolve(),close:()=>phase==='close'?gate.promise:Promise.resolve()},async()=>{if(phase==='authenticate')await gate.promise;return namedRef(action==='child'?'native-child-result.json':'native-parent-partial.json');})),code=>{exit=code;});void work.catch(()=>{});expect(exit).toBe(1);for(let i=0;i<12;i++)await Promise.resolve();expect(visible).toBe(true);expect(exit).toBe(1);gate.resolve();await work;expect(exit).toBe(status==='complete'?0:2);}});
