test('raw sink reserves before exclusive create, retains original write/backpressure and separate fsync/fileClose promises',async()=>{const order:string[]=[],write=held<void>(),fsync=held<void>(),close=held<void>();let auth=0;const sink=await tool.createTrackerATraceSink({reserve:async()=>{order.push('reserve');},open:async()=>{order.push('open');return {write:()=>{order.push('write');return write.promise;},fsync:()=>{order.push('fsync');return fsync.promise;},close:()=>{order.push('close');return close.promise;}};},authenticate:async()=>{auth++;return {path:'tracker-a-case-2-trace.json',bytes:1,sha256:digest};}});expect(order).toEqual(['reserve','open']);expect(sink.created).toBe(true);let written=false;const w=sink.write(new Uint8Array([1])).then(()=>{written=true;});await Promise.resolve();expect(written).toBe(false);write.resolve();await w;const finish=sink.finish();expect(sink.finish()).toBe(finish);expect(sink.fsync).toBe(fsync.promise);expect(sink.fileClose).toBeNull();fsync.resolve();for(let i=0;i<4;i++)await Promise.resolve();expect(sink.fileClose).toBe(close.promise);expect(auth).toBe(0);close.resolve();expect(await finish).toEqual({path:'tracker-a-case-2-trace.json',bytes:1,sha256:digest});expect(auth).toBe(1);expect(order.filter(x=>x==='fsync')).toHaveLength(1);expect(order.filter(x=>x==='close')).toHaveLength(1);await expect(sink.write(new Uint8Array([2]))).rejects.toThrow();});
