test.each(['fsync','close'] as const)('raw sink rejected %s still retains separate close original and cannot authenticate a FileRef',async phase=>{const error=Error(phase),close=held<void>();let auth=0,closes=0;const sink=await tool.createTrackerATraceSink({reserve:async()=>{},open:async()=>({write:async()=>{},fsync:async()=>{if(phase==='fsync')throw error;},close:()=>{closes++;return close.promise;}}),authenticate:async()=>{auth++;return {path:'tracker-a-case-2-trace.json',bytes:0,sha256:digest};}});const finish=sink.finish();for(let i=0;i<6;i++)await Promise.resolve();expect(closes).toBe(1);expect(auth).toBe(0);const failure=expect(finish).rejects.toBe(error);if(phase==='close')close.reject(error);else close.resolve();await failure;expect(auth).toBe(0);});

