 const record=(n:1|2)=>({caseNumber:n,journey:n===1?'follow' as const:'history-reading' as const,threadId:`thread-${n}`,seedRunId:`seed-${n}`,continuationRunId:`continue-${n}`,repetition:`rep-${n}`,completed:true,publicIdle:true,storeEmpty:true,domainReleased:true,originals:MOUNTED_CASE_WITNESS_LABELS.map(label=>({label,status:'fulfilled' as const}))});
