test.each(['prepare','install'] as const)('inventory refuses visible failed or held %s serial publications before CLOSED transition or inventory write',async action=>{for(const phase of ['fsync','close','authenticate'] as const)for(const rejected of [false,true]){const name=action==='prepare'?'tracker-a-profile.json':'installed-admission.json',bundle=bootstrapBundle(),serial=action==='prepare'?tool.constructTrackerAProfile(bundle.intent,bundle.nativePrerequisite,namedRef('native-intent.json')):bundle.installed,raw=Buffer.from(JSON.stringify(serial)+'\n'),gate=held<void>(),failure=Error(phase);let visible:Uint8Array|null=null,exit=0,closes=0;const original=tool.runTrackerAPilotAction(action,()=>tool.closeTrackerAPilotFile(raw,{write:async bytes=>{visible=bytes;},fsync:()=>phase==='fsync'?gate.promise:Promise.resolve(),close:()=>{closes++;return phase==='close'?gate.promise:Promise.resolve();}},async()=>{if(phase==='authenticate')await gate.promise;return namedRef(name);}),code=>{exit=code;});void original.catch(()=>{});for(let i=0;i<12;i++)await Promise.resolve();expect(visible).toEqual(raw);expect(exit).toBe(1);if(rejected){gate.reject(failure);await expect(original).rejects.toBe(failure);expect(closes).toBe(1);}let transitions=0,writes=0,reads=0,inventoryExit=0;const inventory=tool.runTrackerAPilotAction('inventory',async()=>{await tool.admitTrackerAInventory(profileRef,{names:async()=>[name],read:async()=>{reads++;return {raw,bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')};}});transitions++;tool.mountedTrackerAReservation('inventory',[{path:name,bytes:raw.length}]);writes++;},code=>{inventoryExit=code;});await expect(inventory).rejects.toThrow();expect(inventoryExit).toBe(1);expect(transitions).toBe(0);expect(writes).toBe(0);expect(reads).toBe(0);if(!rejected){gate.resolve();await original;expect(closes).toBe(1);}}});
test('inventory requires authenticated runtime publication and original quiescence before its I-only row',async()=>{const f=await publicationFiles(),command=completedCommand('parent'),raw=Buffer.from(JSON.stringify(command)+'\n');f.files.set('parent-result.json',{raw,bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')});let admitted=false;await tool.admitTrackerAInventory(profileRef,{names:async()=>['parent-started.json',...f.files.keys()],read:f.read});admitted=true;expect(admitted).toBe(true);command.original.exitCode=1;command.exit!.exitCode=1;const failed=Buffer.from(JSON.stringify(command)+'\n');f.files.set('parent-result.json',{raw:failed,bytes:failed.length,sha256:createHash('sha256').update(failed).digest('hex')});await expect(tool.admitTrackerAInventory(profileRef,{names:async()=>['parent-started.json',...f.files.keys()],read:f.read})).rejects.toThrow();});
test('pilot worker full options/profile admission precedes named import and nonserialized publication third argument',async()=>{const b=bootstrapBundle(),assets=bootstrapAssets(),profile=tool.constructTrackerAProfile(b.intent,b.nativePrerequisite,namedRef('native-intent.json')),options={prerequisites:b,browserEndpoint:'ws://127.0.0.1:1234/a',assets};const calls:string[]=[],profileBytes=Buffer.from(JSON.stringify(profile)+'\n');const publication={profileRef:{path:'tracker-a-profile.json',bytes:profileBytes.length,sha256:createHash('sha256').update(profileBytes).digest('hex')},reserveTraceSink:async()=>{throw Error('not requested');}};const result=await tool.invokeTrackerAWorker({options,prerequisites:b,assets,profile,intentRef:namedRef('native-intent.json')},{importWorker:async()=>{calls.push('import');return {runNativeMountedTrackerAPilot:async(actual,diagnostics,pub)=>{calls.push('pilot');expect(actual).toEqual(options);expect(diagnostics).toBe('diagnostics');expect(pub).toBe(publication);expect(Object.keys(actual as object)).toEqual(['prerequisites','browserEndpoint','assets']);return 'original-result';}};},diagnostics:'diagnostics',publication});expect(result).toBe('original-result');expect(calls).toEqual(['import','pilot']);for(const change of [{...options,extra:true},{...options,prerequisites:{...b,nativePrerequisite:{...b.nativePrerequisite,archiveBytes:0}}}]){calls.length=0;await expect(tool.invokeTrackerAWorker({options:change,prerequisites:b,assets,profile,intentRef:namedRef('native-intent.json')},{importWorker:async()=>{calls.push('must not import');return {};},diagnostics:null,publication})).rejects.toThrow();expect(calls).toEqual([]);}});


// These inspect fixed workflow SOURCE and supplied original ports; they do not
// execute GitHub expressions, a bootstrap CLI, SDK, browser or native process.
async function trackerWorkflowSource(){return readFile(new URL('../.github/workflows/hosted-copilot-tracker-a.yml',import.meta.url),'utf8').catch(error=>{if((error as NodeJS.ErrnoException).code==='ENOENT')return '';throw error;});}
function assertTrackerWorkflowBoundary(source:string){
 const blocks=source.split(/^      - name: /m).slice(1);
 const runtime=blocks.find(block=>block.includes('id: runtime\n'));
 const inventory=blocks.find(block=>block.includes('id: artifacts\n'));
 expect(runtime,'actual fixed runtime step').toBeDefined();
 expect(runtime).toContain('run: node --experimental-import-meta-resolve tools/hosted-copilot-mounted-bootstrap.mjs run\n');
 expect(runtime).not.toMatch(/^        if:/m);
 expect(inventory).toContain("if: always() && steps.runtime.outcome == 'success'\n");
 expect(inventory).toContain('run: node --experimental-import-meta-resolve tools/hosted-copilot-mounted-bootstrap.mjs inventory\n');
 expect(blocks.find(block=>block.includes('uses: actions/upload-artifact@'))).toContain("if: always() && steps.artifacts.outcome == 'success'\n");
 expect(source).not.toMatch(/continue-on-error|\|\||&&\s*(?:true|:)|set\s+\+e|exit\s+0|HOSTED_.*(?:ELIGIB|SUCCESS)/);
 const runs=blocks.filter(block=>block.includes('run: '));
 expect(runs.map(block=>block.match(/bootstrap\.mjs (\w+)\n/)?.[1])).toEqual(['prepare','install','provision','run','inventory']);
 for(const block of runs.slice(0,3))expect(block).not.toMatch(/^        if:/m);
 expect(source).toContain('run-name: hosted-copilot-react-tracker-json-a-v1\n');
}
test('fixed pilot SOURCE gates inventory on original runtime success and upload on inventory success',async()=>{assertTrackerWorkflowBoundary(await trackerWorkflowSource());});
test.each(['native-result.json','tracker-a-result.json'] as const)('fixed workflow refuses inventory eligibility while full visible %s publication originals fail or remain held',async name=>{
 const source=await trackerWorkflowSource();
 for(const phase of ['fsync','close','authenticate'] as const)for(const rejected of [false,true]){
  const value=await outerPublication(),gate=held<void>(),failure=Error(phase);let exit=0,visible:Uint8Array|null=null,closes=0,full:any;
  const publish=async(serial:unknown,path:'native-result.json'|'tracker-a-result.json')=>{const raw=Buffer.from(JSON.stringify(serial)+'\n');if(path!==name)return;full=serial;await tool.closeTrackerAPilotFile(raw,{write:async bytes=>{visible=bytes;},fsync:()=>phase==='fsync'?gate.promise:Promise.resolve(),close:()=>{closes++;return phase==='close'?gate.promise:Promise.resolve();}},async()=>{if(phase==='authenticate')await gate.promise;return {path,bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')};});};
  const work=tool.runTrackerAPilotAction('run',()=>tool.publishTrackerAOuterResult(value,{writeNative:serial=>publish(serial,'native-result.json'),authenticateNative:async()=>({path:'native-result.json' as const,bytes:1,sha256:digest}),writeTracker:serial=>publish(serial,'tracker-a-result.json')}),code=>{exit=code;});void work.catch(()=>{});
  for(let i=0;i<40;i++)await Promise.resolve();
  expect(visible).not.toBeNull();expect(JSON.parse(Buffer.from(visible!).toString('utf8'))).toEqual(full);expect(exit).toBe(1);
  // Genuine authenticated parent0 passes its own gate. It cannot establish
  // original closure of the later outer serial publication.
  const f=await publicationFiles(),command=completedCommand('parent'),parentRaw=Buffer.from(JSON.stringify(command)+'\n');f.files.set('parent-result.json',{raw:parentRaw,bytes:parentRaw.length,sha256:createHash('sha256').update(parentRaw).digest('hex')});
  await tool.admitTrackerAInventory(profileRef,{names:async()=>['parent-started.json',...f.files.keys()],read:f.read});expect(exit).toBe(1);
  if(rejected){gate.reject(failure);await expect(work).rejects.toBe(failure);expect(exit).toBe(1);}else{gate.resolve();await work;expect(exit).toBe(0);}expect(closes).toBe(1);
 }
 assertTrackerWorkflowBoundary(source);
});
test('coherent pilot source membership and fixed next source profiles are selected',async()=>{
 const source=await readFile(new URL('./support/hosted-copilot-context.ts',import.meta.url),'utf8');
 const literal=source.split('export const COPILOT_PRODUCTION_SOURCES=Object.freeze([')[1]!.split(']);')[0]!;
 const paths=[...literal.matchAll(/'([^']+)'/g)].map(match=>match[1]!);expect(paths).toHaveLength(79);expect(new Set(paths).size).toBe(79);
 for(const [before,after] of [['.github/workflows/hosted-copilot-mounted.yml','.github/workflows/hosted-copilot-tracker-a.yml'],['apps/copilotkit/runtime/mounted-native.ts','apps/copilotkit/runtime/mounted-tracker-a-trace.ts'],['apps/copilotkit/runtime/mounted-tracker-a-trace.ts','apps/copilotkit/runtime/mounted-tracker-a.ts'],['tests/copilotkit-mounted-conformance.test.ts','tests/copilotkit-mounted-tracker-a-trace.test.ts'],['tests/copilotkit-mounted-tracker-a-trace.test.ts','tests/copilotkit-mounted-tracker-a.test.ts']])expect(paths.indexOf(after!)).toBe(paths.indexOf(before!)+1);
 expect(source).toContain("context.releaseId!=='hosted-copilot-react-production-build-v42'");
 expect(await readFile(new URL('../.github/workflows/hosted-copilot-mounted.yml',import.meta.url),'utf8')).toContain('run-name: hosted-copilot-react-h100-r6400-v7\n');
});
